#include <iostream>
#include <vector>
#include <string>
using namespace std;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    long long h;
    long long w;
    long long moves;
    long long r;
    long long c;
    cin >> h >> w >> moves >> r >> c;

    const long long MOD = 1000000007;
    vector<vector<long long>> cur(h, vector<long long>(w, 0));
    cur[r][c] = 1;
    long long answer = 0;
    int dx[4] = {1, -1, 0, 0}, dy[4] = {0, 0, 1, -1};
    for (long long m = 0; m < moves; m++) {
        vector<vector<long long>> next(h, vector<long long>(w, 0));
        for (int i = 0; i < h; i++) {
            for (int j = 0; j < w; j++) {
                long long v = cur[i][j];
                if (v == 0) continue;
                for (int d = 0; d < 4; d++) {
                    int a = i + dx[d], b = j + dy[d];
                    if (a >= 0 && a < h && b >= 0 && b < w) next[a][b] = (next[a][b] + v) % MOD;
                    else answer = (answer + v) % MOD;
                }
            }
        }
        cur = next;
    }
    cout << answer << "\n";

    return 0;
}

