import java.io.*;
import java.util.*;

public class Main {
    static BufferedReader in = new BufferedReader(new InputStreamReader(System.in));
    static StringTokenizer tokens = new StringTokenizer("");

    static String next() throws IOException {
        while (!tokens.hasMoreTokens()) {
            tokens = new StringTokenizer(in.readLine());
        }
        return tokens.nextToken();
    }

    public static void main(String[] args) throws IOException {
        long h = Long.parseLong(next());
        long w = Long.parseLong(next());
        long moves = Long.parseLong(next());
        long r = Long.parseLong(next());
        long c = Long.parseLong(next());

        final long MOD = 1000000007L;
        int rowsCount = (int) h, colsCount = (int) w;
        long[][] cur = new long[rowsCount][colsCount];
        long[][] next = new long[rowsCount][colsCount];
        cur[(int) r][(int) c] = 1;
        long answer = 0;
        int[] dx = {1, -1, 0, 0}, dy = {0, 0, 1, -1};
        for (int m = 0; m < moves; m++) {
            for (int i = 0; i < rowsCount; i++) Arrays.fill(next[i], 0);
            for (int i = 0; i < rowsCount; i++) {
                for (int j = 0; j < colsCount; j++) {
                    long v = cur[i][j];
                    if (v == 0) continue;
                    for (int d = 0; d < 4; d++) {
                        int a = i + dx[d], b = j + dy[d];
                        if (a >= 0 && a < rowsCount && b >= 0 && b < colsCount) next[a][b] = (next[a][b] + v) % MOD;
                        else answer = (answer + v) % MOD;
                    }
                }
            }
            long[][] swap = cur;
            cur = next;
            next = swap;
        }
        System.out.println(answer);
    }
}
